export const CONTROLS_BY_CATEGORY = CONTROLS_CATALOG.reduce((acc, control) => {
  if (!acc[control.category]) acc[control.category] = [];
  acc[control.category].push(control);
  return acc;
}, {});

export const getControlById = (id) => CONTROLS_CATALOG.find((c) => c.id === id);

export default CONTROLS_CATALOG;
